class Solution {
public:
    int maxIncreasingCells(vector<vector<int>>& mat) {
        int m = mat.size(), n = mat[0].size();
        map<int, vector<pair<int, int>>> val_to_cells;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                val_to_cells[mat[r][c]].emplace_back(r, c);
            }
        }
        vector<int> row_max(m, 0), col_max(n, 0);
        for (auto& [val, cells] : val_to_cells) {
            vector<int> best(cells.size());
            for (int i = 0; i < (int)cells.size(); ++i) {
                int r = cells[i].first, c = cells[i].second;
                best[i] = 1 + max(row_max[r], col_max[c]);
            }
            for (int i = 0; i < (int)cells.size(); ++i) {
                int r = cells[i].first, c = cells[i].second;
                row_max[r] = max(row_max[r], best[i]);
                col_max[c] = max(col_max[c], best[i]);
            }
        }
        int ans = 0;
        for (int x : row_max) ans = max(ans, x);
        for (int x : col_max) ans = max(ans, x);
        return ans;
    }
};

import java.util.ArrayList;
import java.util.List;
import java.util.TreeMap;

class Solution {
    public int maxIncreasingCells(int[][] mat) {
        int m = mat.length, n = mat[0].length;
        TreeMap<Integer, List<int[]>> map = new TreeMap<>();
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                map.computeIfAbsent(mat[r][c], k -> new ArrayList<>()).add(new int[]{r, c});
            }
        }
        int[] rowMax = new int[m];
        int[] colMax = new int[n];
        for (int val : map.keySet()) {
            List<int[]> cells = map.get(val);
            int[] best = new int[cells.size()];
            for (int i = 0; i < cells.size(); i++) {
                int r = cells.get(i)[0], c = cells.get(i)[1];
                best[i] = 1 + Math.max(rowMax[r], colMax[c]);
            }
            for (int i = 0; i < cells.size(); i++) {
                int r = cells.get(i)[0], c = cells.get(i)[1];
                rowMax[r] = Math.max(rowMax[r], best[i]);
                colMax[c] = Math.max(colMax[c], best[i]);
            }
        }
        int ans = 0;
        for (int x : rowMax) ans = Math.max(ans, x);
        for (int x : colMax) ans = Math.max(ans, x);
        return ans;
    }
}

var maxIncreasingCells = function(mat) {
    const m = mat.length;
    const n = mat[0].length;
    const valToCells = new Map();
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            const v = mat[r][c];
            if (!valToCells.has(v)) valToCells.set(v, []);
            valToCells.get(v).push([r, c]);
        }
    }
    const sortedVals = Array.from(valToCells.keys()).sort((a, b) => a - b);
    const rowMax = new Array(m).fill(0);
    const colMax = new Array(n).fill(0);
    for (const val of sortedVals) {
        const cells = valToCells.get(val);
        const best = [];
        for (const [r, c] of cells) {
            best.push(1 + Math.max(rowMax[r], colMax[c]));
        }
        for (let i = 0; i < cells.length; i++) {
            const [r, c] = cells[i];
            rowMax[r] = Math.max(rowMax[r], best[i]);
            colMax[c] = Math.max(colMax[c], best[i]);
        }
    }
    let ans = 0;
    for (const x of rowMax) ans = Math.max(ans, x);
    for (const x of colMax) ans = Math.max(ans, x);
    return ans;
};
